<?php
require_once __DIR__.'/config/auth.php';petcare_require_admin();require_once __DIR__.'/config/workflow.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
 petcare_check_csrf();$id=(int)($_POST['plano_id']??0);$q=$pdo->prepare('SELECT id FROM planos WHERE id=?');$q->execute([$id]);if(!$q->fetchColumn())petcare_back('Plano inválido.');
 try{$pdo->beginTransaction();$pdo->prepare('DELETE FROM plano_servicos WHERE plano_id=?')->execute([$id]);foreach(array_unique(array_map('intval',(array)($_POST['servicos']??[]))) as $sid){$q=$pdo->prepare('SELECT id FROM servicos WHERE id=?');$q->execute([$sid]);if($q->fetchColumn())$pdo->prepare('INSERT INTO plano_servicos(plano_id,servico_id) VALUES(?,?)')->execute([$id,$sid]);}$pdo->commit();petcare_flash('Serviços do plano atualizados.','success');header('Location:admin_plano_servicos.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();petcare_back('Não foi possível atualizar o plano.');}
}
$plans=$pdo->query('SELECT id,nome FROM planos ORDER BY nome')->fetchAll();$services=$pdo->query('SELECT id,nome FROM servicos ORDER BY nome')->fetchAll();$links=$pdo->query('SELECT plano_id,servico_id FROM plano_servicos')->fetchAll();$map=[];foreach($links as $l)$map[$l['plano_id']][]=(int)$l['servico_id'];$pageTitle='Serviços dos planos';require __DIR__.'/includes/header.php';?>
<header class="topbar"><div><h1>Serviços permitidos em cada plano</h1><p>O proprietário define quais serviços consomem o saldo de cada plano.</p></div></header>
<?php foreach($plans as $p):?><div class="card" style="padding:16px;margin-bottom:12px"><h2><?=htmlspecialchars($p['nome'])?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(petcare_csrf_token())?>"><input type="hidden" name="plano_id" value="<?=$p['id']?>"><?php foreach($services as $s):?><label style="display:block"><input type="checkbox" name="servicos[]" value="<?=$s['id']?>" <?=in_array((int)$s['id'],$map[$p['id']]??[],true)?'checked':''?>> <?=htmlspecialchars($s['nome'])?></label><?php endforeach;?><button class="btn primary">Salvar serviços permitidos</button></form></div><?php endforeach;?>
